// dp[mask][v]: 0번 도시에서 출발해 mask의 도시들을 한 번씩 방문하고 v에 있을 때 최소 비용
// (mask는 방문한 도시의 집합, 0번과 v를 포함)
dp[1][0] = 0;
for (int mask = 1; mask < (1 << n); mask++)
    for (int v = 0; v < n; v++) {
        if (dp[mask][v] == INF) continue;
        for (int u = 0; u < n; u++)
            if (!(mask & (1 << u)))                     // u를 아직 방문하지 않았으면
                dp[mask | (1 << u)][u] = min(dp[mask | (1 << u)][u], dp[mask][v] + d[v][u]);
    }
// 답: 모든 v에 대해 dp[(1<<n)-1][v] + d[v][0]의 최솟값

