// 일꾼 n명에게 일 n개를 하나씩 맡길 때 비용 합의 최솟값
// dp[mask]: 앞의 일꾼 popcount(mask)명에게 mask의 일들을 맡긴 최소 비용
dp[0] = 0;
for (int mask = 0; mask < (1 << n); mask++) {
    int w = __builtin_popcount(mask);                   // 다음에 맡길 일꾼 번호
    for (int j = 0; j < n; j++)
        if (!(mask & (1 << j)))
            dp[mask | (1 << j)] = min(dp[mask | (1 << j)], dp[mask] + cost[w][j]);
}

